SourceCode.Declaration:
[FormControlAttribute('WalkMePage', '', classstr(DAXVWalkMeControlBuild))]
//Form template control for walk me control
class DAXVWalkMeControl extends FormTemplateControl
{
    FormProperty url;
 
}

Method.Source:
   public void new(FormBuildControl _build, FormRun _formRun)
   {
       super(_build, _formRun);

       this.setTemplateId('WalkMePage');
       this.setResourceBundleName('/resources/html/WalkMePage'); // Call to HTMl Page for Walkme

       url = properties.addProperty(methodStr(DAXVWalkMeControl, parmurl), Types::String); // Assign the URL control value from form setup 
   }

   //Build control and apply to the parameter
   public void applyBuild()
   {
       super();

       DAXVWalkMeControlBuild build = this.build(); // Constructing the ControlAccess Build

       if (build)
       {
           this.parmURL(build.parmURL());
       }
   }

   //Attribute declaration for URL
   [FormPropertyAttribute(FormPropertyKind::Value, "URL")]
   public str parmURL(str _value = url.parmValue())
   {
       if (!prmIsDefault(_value))
       {
           url.setValueOrBinding(_value);
       }

       return url.parmValue();
   }
